import 'package:flutter/material.dart'; import '../core/api_client.dart';
class EarningsScreen extends StatelessWidget { const EarningsScreen({super.key}); @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: const Text('My Earnings')), body: FutureBuilder<Map<String, dynamic>>(future: ApiClient().earnings(), builder: (_, snapshot) { if (snapshot.connectionState != ConnectionState.done) return const Center(child: CircularProgressIndicator()); final rows = ((snapshot.data?['data'] as Map<String, dynamic>?)?['data'] as List<dynamic>? ?? []); if (rows.isEmpty) return const Center(child: Text('Completed delivery earnings will appear here.')); return ListView.separated(padding: const EdgeInsets.all(16), itemCount: rows.length, separatorBuilder: (_, __) => const SizedBox(height: 10), itemBuilder: (_, i) { final row = rows[i] as Map<String, dynamic>; return Card(child: ListTile(leading: const CircleAvatar(child: Icon(Icons.currency_rupee)), title: Text('₹${row['net_amount'] ?? 0}', style: const TextStyle(fontWeight: FontWeight.bold)), subtitle: Text(row['status']?.toString() ?? 'pending'), trailing: Text(row['created_at']?.toString().split('T').first ?? ''))); }); })); }

